import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_UNIT_SECONDS = {
    'W': 604800,
    'D': 86400,
    'H': 3600,
    'M': 60,
    'S': 1,
}


def _parse_iso(text: str) -> int:
    match = re.fullmatch(
        r'P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?'
        r'(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?',
        text,
    )
    if not match or not any(match.groups()):
        raise ValueError(f"Invalid ISO 8601 duration: {text!r}")

    weeks, days, hours, minutes, seconds = match.groups()
    total = 0.0
    if weeks:
        total += float(weeks) * _ISO_UNIT_SECONDS['W']
    if days:
        total += float(days) * _ISO_UNIT_SECONDS['D']
    if hours:
        total += float(hours) * _ISO_UNIT_SECONDS['H']
    if minutes:
        total += float(minutes) * _ISO_UNIT_SECONDS['M']
    if seconds:
        total += float(seconds) * _ISO_UNIT_SECONDS['S']

    return round(total)


def _parse_clock(text: str) -> int:
    parts = text.split(':')
    if len(parts) not in (2, 3):
        raise ValueError(f"Invalid clock duration: {text!r}")
    for part in parts:
        if not re.fullmatch(r'\d+', part):
            raise ValueError(f"Invalid clock duration: {text!r}")
    nums = [int(p) for p in parts]
    if len(nums) == 2:
        minutes, seconds = nums
        hours = 0
    else:
        hours, minutes, seconds = nums
    return hours * 3600 + minutes * 60 + seconds


def _parse_components(text: str) -> int:
    if not re.fullmatch(r'(?:\d+(?:\.\d+)?[a-zA-Z]+)+', text):
        raise ValueError(f"Invalid duration: {text!r}")

    total = 0.0
    for value, unit in re.findall(r'(\d+(?:\.\d+)?)([a-zA-Z]+)', text):
        unit_lower = unit.lower()
        if unit_lower not in _UNIT_SECONDS:
            raise ValueError(f"Unknown unit: {unit!r}")
        total += float(value) * _UNIT_SECONDS[unit_lower]

    return round(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("Duration must be a string")

    stripped = text.strip()
    if not stripped:
        raise ValueError("Empty duration")

    if re.fullmatch(r'\d+', stripped):
        return int(stripped)

    if re.fullmatch(r'\d+:\d+(?::\d+)?', stripped):
        return _parse_clock(stripped)

    if stripped.upper().startswith('P'):
        return _parse_iso(stripped)

    no_space = stripped.replace(' ', '')
    return _parse_components(no_space)

